const urlOptions=new URLSearchParams(window.location.search);
const requestedDirection=({signal:'pulse',platinum:'atlas'})[urlOptions.get('direction')]||urlOptions.get('direction');
const direction=['studio','pulse','atlas'].includes(requestedDirection)?requestedDirection:'original';
