const paths={collider:'<ellipse cx="12" cy="12" rx="10" ry="4.5" transform="rotate(-35 12 12)"/><ellipse cx="12" cy="12" rx="10" ry="4.5" transform="rotate(35 12 12)"/><circle cx="12" cy="12" r="1.5"/>',home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',plus:'<path d="M12 5v14M5 12h14"/>',mail:'<rect x="3" y="5" width="18" height="14" rx="3"/><path d="m3 7 9 6 9-6"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M9 21h6"/>',settings:'<path d="m9 3-1 3-3 1-2 3 2 3v4l3 2 4-1 3 2 3-2v-3l3-3-2-4-3-1-1-4z"/><circle cx="12" cy="12" r="3"/>',heart:'<path d="M20.5 4.5a5 5 0 0 0-7 0L12 6l-1.5-1.5a5 5 0 0 0-7 7L12 20l8.5-8.5a5 5 0 0 0 0-7z"/>',comment:'<path d="M21 11.5a8.5 8.5 0 0 1-8.5 8.5H4l-2 2v-9.5A9.5 9.5 0 0 1 12 3a8.5 8.5 0 0 1 9 8.5z"/>',repost:'<path d="m4 8 3-3 3 3M7 5v10a3 3 0 0 0 3 3h2m8-2-3 3-3-3m3 3V9a3 3 0 0 0-3-3h-2"/>',bookmark:'<path d="M6 3h12v18l-6-4-6 4z"/>',share:'<path d="M12 16V3m-4 4 4-4 4 4M5 11H3v10h18V11h-2"/>',more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',back:'<path d="m15 5-7 7 7 7"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',job:'<rect x="3" y="7" width="18" height="14" rx="2"/><path d="M8 7V3h8v4M3 12h18m-11 0v3h4v-3"/>',gig:'<path d="m13 2-9 12h7l-1 8 10-13h-7z"/>',collab:'<circle cx="8" cy="8" r="3"/><path d="M2 20v-2a6 6 0 0 1 12 0v2M16 5a3 3 0 0 1 0 6m2 3a5 5 0 0 1 4 5v1"/>',event:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 2v6M17 2v6M3 11h18M7 15h3m4 0h3"/>',update:'<path d="m16 3 5 5-11 11-7 2 2-7zM14 5l5 5"/>',pin:'<path d="M19 9c0 6-7 12-7 12S5 15 5 9a7 7 0 0 1 14 0z"/><circle cx="12" cy="9" r="2"/>',globe:'<circle cx="12" cy="12" r="10"/><ellipse cx="12" cy="12" rx="4.8" ry="10"/><path d="M2 12h20M4 6h16M4 18h16"/>',check:'<path d="m5 12 4 4L19 6"/>',send:'<path d="m3 3 19 9-19 9 4-9zM7 12h15"/>',shield:'<path d="m12 2 9 4v6c0 6-9 10-9 10S3 18 3 12V6z"/><path d="m8 12 3 3 5-6"/>',mute:'<path d="m3 3 18 18M11 5 6 9H3v6h3l5 4v-7m4-6a8 8 0 0 1 5 12"/>',flag:'<path d="M4 22V3c7-5 9 5 16 0v11c-7 5-9-5-16 0"/>',block:'<circle cx="12" cy="12" r="9"/><path d="m6 6 12 12"/>',chart:'<path d="M3 3v18h18M7 17v-5m5 5V7m5 10v-8"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z"/>',file:'<path d="M5 2h9l5 5v15H5zM14 2v6h5M8 13h8m-8 4h6"/>',copy:'<rect x="8" y="8" width="12" height="13" rx="2"/><path d="M16 8V3H3v13h5"/>',out:'<path d="M13 3h8v8m0-8L10 14M9 5H3v16h16v-6"/>'};
const icon=(name,cls='')=>`<svg class="${cls}" aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round">${paths[name]||paths.spark}</svg>`;
let state=initialState(),persistent=true;try{const saved=JSON.parse(localStorage.getItem(storageKey)||'null');if(saved?.schema===2&&Array.isArray(saved.posts)&&saved.profile&&saved.settings&&['following','saved','liked','threads','applications','blocked','activity'].every(k=>Array.isArray(saved[k])))state=saved;}catch{persistent=false}
const stateDefaults=initialState();
state.settings={...stateDefaults.settings,...state.settings};state.draft={...stateDefaults.draft,...state.draft};
for(const key of ['muted','reposted','evidence','reports'])if(!Array.isArray(state[key]))state[key]=stateDefaults[key];
state.collider=normalizeCollider(state.collider,state.profile);
function applyDesignDefaults(){if(direction!=='original'&&state.designDirection!==direction){state.settings.theme=direction==='atlas'?'light':'dark';state.designDirection=direction;}}
applyDesignDefaults();
const initialView=['feed','discover','inbox','profile','settings','collider'].includes(urlOptions.get('view'))?urlOptions.get('view'):'feed';
const ui={view:initialView,feedTab:'for-you',feedType:'all',discoverTab:'opportunities',query:'',discoverType:'all',remote:false,paid:false,profileId:'me',profileTab:'posts',inboxTab:'messages',savedTab:'saved',modal:null,draftReview:null,interest:null,commentDrafts:{}};
const screen=$('#screen'),modal=$('#modal'),modalBody=$('#modalBody');let toastTimer;
const colliderFeature=createColliderFeature({getState:()=>state,E,icon,allPosts,openModal,persist,render,navigate,notify});
function persist(){try{localStorage.setItem(storageKey,JSON.stringify(state));persistent=true;}catch{persistent=false}$('#storageStatus').textContent=persistent?'Only on this browser':'Session only · storage unavailable';}
function notify(text){if(modal.open){let feedback=$('#modalFeedback');if(!feedback){feedback=document.createElement('div');feedback.id='modalFeedback';feedback.className='modal-feedback';feedback.setAttribute('role','status');modal.append(feedback)}feedback.textContent=text;feedback.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>{feedback.hidden=true},3000);return;}$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2500)}
function avatar(id,extra=''){const p=person(state,id);return `<button class="avatar ${p.color} ${extra}" data-action="profile" data-value="${E(id)}" aria-label="Open ${E(p.name)}’s profile">${E(p.initials)}</button>`}
function setTheme(){let theme=state.settings.theme;if(theme==='system')theme=window.matchMedia?.('(prefers-color-scheme: light)').matches?'light':'dark';document.body.dataset.theme=theme;document.body.classList.toggle('reduce-motion',state.settings.reduceMotion);}
function unreadCount(){return state.threads.filter(t=>t.unread&&!state.blocked.includes(t.id)&&(!t.request||state.settings.messages==='Everyone'||state.following.includes(t.id))).length}
const sections=[['feed','home','Feed'],['discover','search','Discover'],['create','plus','Create'],['inbox','mail','Inbox'],['profile','user','Passport']];
function header(){const root=['feed','discover','inbox','profile'].includes(ui.view);const titles={collider:'Lynk Collider',discover:'Discover',inbox:'Inbox',profile:ui.profileId==='me'?'Your Passport':person(state,ui.profileId)?.name,saved:'Your opportunities',settings:'Settings',notifications:'Activity',progress:'Progress',research:'Research notebook'};const count=state.activity.filter(a=>!a.read&&state.settings[a.kind]).length;$('#header').innerHTML=`${ui.view==='feed'?'<button class="wordmark" data-action="navigate" data-value="feed" aria-label="FYND home">FYND<span>.</span></button>':`<div style="display:flex;align-items:center;min-width:0">${root?'':`<button class="icon-button" data-action="navigate" data-value="${ui.view==='notifications'?'feed':ui.view==='collider'?'discover':'profile'}" aria-label="Go back">${icon('back')}</button>`}<span class="header-title">${E(titles[ui.view]||'FYND')}</span></div>`}<div class="header-actions">${ui.view==='feed'||ui.view==='discover'?`<button class="icon-button" data-action="navigate" data-value="collider" aria-label="Lynk Collider">${icon('collider')}</button><button class="icon-button" data-action="navigate" data-value="saved" aria-label="Saved opportunities">${icon('bookmark')}</button><button class="icon-button" data-action="navigate" data-value="notifications" aria-label="Activity${count?', unread notifications':''}">${icon('bell')}${count?'<i class="badge-dot"></i>':''}</button>`:ui.view==='profile'?`<button class="icon-button" data-action="navigate" data-value="settings" aria-label="Settings">${icon('settings')}</button>`:ui.view==='inbox'?`<button class="icon-button" data-action="new-message" aria-label="New message">${icon('update')}</button>`:''}</div>`;const navHTML=sections.map(([id,ic,label])=>`<button class="nav-item ${id==='create'?'nav-create ':''}${ui.view===id?'active':''}" data-action="${id==='create'?'compose':'navigate'}" ${id==='create'?'':`data-value="${id}"`} ${ui.view===id?'aria-current="page"':''} aria-label="${label}">${id==='create'?`<span class="create-shape">${icon(ic)}</span>`:icon(ic)}<span>${label}</span>${id==='inbox'&&unreadCount()?`<b class="tiny-count">${unreadCount()}</b>`:''}</button>`).join('');$('#bottomNav').innerHTML=navHTML;$('#desktopNav').innerHTML=desktopNavigation(ui.view,'demo',icon);if(!isEmbedded){const actions=$('#header .header-actions');actions.classList.add('preview-header-actions');actions.insertAdjacentHTML('beforeend',`<button class="header-tool-button" data-action="tools" aria-label="Open all tools" aria-haspopup="dialog">${icon('more')}<span>Tools</span></button>`);}}
function tabs(items,selected,action){return `<div class="tabs" role="tablist">${items.map(([value,label])=>`<button class="tab ${value===selected?'active':''}" role="tab" aria-selected="${value===selected}" data-action="${action}" data-value="${value}">${label}</button>`).join('')}</div>`}
function filters(selected,action,includeUpdate=false){return `<div class="filter-row">${[['all','All'],['job','Jobs'],['gig','Gigs'],['collab','Collabs'],['event','Events'],...(includeUpdate?[['update','Updates']]:[])].map(([id,l])=>`<button class="chip ${selected===id?'active':''}" data-action="${action}" data-value="${id}" aria-pressed="${selected===id}">${icon(id==='all'?'spark':id)}<span>${l}</span></button>`).join('')}</div>`}
function empty(title,text,ic='search',button=''){return `<div class="empty">${icon(ic)}<h3>${E(title)}</h3><p>${E(text)}</p>${button}</div>`}
function opportunityCard(p){return `<button class="opportunity ${E(p.tone||'sky')}" data-kind="${E(p.type)}" data-action="detail" data-value="${E(p.id)}"><div class="opportunity-top"><span class="type-label">${icon(p.type)}${E(types[p.type])}</span><span class="org-label">${E(p.org)}</span></div><h3>${E(p.title)}</h3><div class="opportunity-meta"><span>${E(p.pay)}</span><span>${E(p.location)}</span></div><div class="opportunity-bottom"><span>${E(p.detail)}</span><b>${icon('arrow')}</b></div></button>`}
function post(p,{detail=false}={}){const author=person(state,p.author);const own=p.author==='me';return `<article class="post" data-post="${E(p.id)}">${state.reposted.includes(p.id)?`<div class="repost-context">${icon('repost')} You reposted</div>`:''}<div class="post-head">${avatar(p.author)}<button class="post-identity" data-action="profile" data-value="${E(p.author)}"><span class="author-name">${E(author.name)}</span><span class="author-meta">@${E(author.handle)} · ${E(p.age)}${p.audience==='Followers'?' · Followers':''}</span></button>${!own?`<button class="follow-inline" data-action="follow" data-value="${E(p.author)}" aria-pressed="${state.following.includes(p.author)}">${state.following.includes(p.author)?'Following':'+ Follow'}</button>`:''}<button class="icon-button" data-action="post-menu" data-value="${E(p.id)}" aria-label="More options for ${E(author.name)}’s post">${icon('more')}</button></div><p class="post-text">${E(p.text)}</p><div class="tags">${p.tags.map(t=>`<button class="tag" data-action="topic" data-value="${E(t)}">#${E(t)}</button>`).join('')}</div>${p.type!=='update'?opportunityCard(p):p.image?`<button style="padding:0;display:block;width:100%" data-action="work" data-value="${E(p.id)}" aria-label="Open Flow work sample"><img class="post-image" src="${E(p.image)}" alt="Cobalt glass and brushed silver ribbons from a fictional material study" loading="lazy" width="1448" height="1086"></button><p class="image-caption">FLOW / MATERIAL STUDIES · SAMPLE WORK</p>`:''}<div class="post-actions"><button class="social-action ${state.liked.includes(p.id)?'liked':''}" data-action="like" data-value="${E(p.id)}" aria-label="${state.liked.includes(p.id)?'Unlike':'Like'} post by ${E(author.name)}" aria-pressed="${state.liked.includes(p.id)}">${icon('heart')}<span>${p.likes+(state.liked.includes(p.id)?1:0)}</span></button><button class="social-action" data-action="comments" data-value="${E(p.id)}" aria-label="Comments on ${E(author.name)}’s post">${icon('comment')}<span>${p.comments.length||''}</span></button><button class="social-action ${state.reposted.includes(p.id)?'reposted':''}" data-action="repost" data-value="${E(p.id)}" aria-label="${state.reposted.includes(p.id)?'Undo repost':'Repost'} by ${E(author.name)}" aria-pressed="${state.reposted.includes(p.id)}">${icon('repost')}<span>${p.reposts+(state.reposted.includes(p.id)?1:0)}</span></button><button class="social-action ${state.saved.includes(p.id)?'saved':''}" data-action="save" data-value="${E(p.id)}" aria-label="${state.saved.includes(p.id)?'Unsave':'Save'} post by ${E(author.name)}" aria-pressed="${state.saved.includes(p.id)}">${icon('bookmark')}</button><button class="social-action" data-action="share" data-value="${E(p.id)}" aria-label="Copy post by ${E(author.name)}">${icon('share')}</button></div></article>`}
function feed(){const rows=feedPosts(state,{following:ui.feedTab==='following',type:ui.feedType});return tabs([['for-you','For you'],['following','Following']],ui.feedTab,'feed-tab')+filters(ui.feedType,'feed-type',true)+`<div class="compose-prompt">${avatar('me')}<button data-action="compose">What are you putting into the world?</button><span class="compose-symbol">${icon('update')}</span></div>`+(rows.length?rows.map(p=>post(p)).join(''):empty('Your feed, your people','Follow people in Discover, or try another post type.','collab','<button class="button" data-action="navigate" data-value="discover">Discover people</button>'))+`<div class="empty"><p>You’re caught up with this sample feed.</p></div>`}
function personRow(p){const blocked=state.blocked.includes(p.id);return `<div class="person-row">${avatar(p.id)}<button class="person-info" data-action="profile" data-value="${E(p.id)}"><strong>${E(p.name)}</strong><small>${E(p.role)}</small></button><button class="pill-button ${state.following.includes(p.id)?'outline':''}" data-action="follow" data-value="${E(p.id)}" aria-pressed="${state.following.includes(p.id)}" ${blocked?'disabled':''}>${state.following.includes(p.id)?'Following':'Follow'}</button></div>`}
const topicList=['ProductDesign','BuildTogether','Freelance','DesignCommunity'];
function discoverResults(){if(ui.discoverTab==='people'){const q=ui.query.trim().replace(/^@/,'').toLowerCase();const result=people.filter(p=>p.id!=='me'&&!state.blocked.includes(p.id)&&[p.name,p.handle,p.role,...p.skills].join(' ').toLowerCase().includes(q));return `<div class="pad">${result.length?result.map(personRow).join(''):empty('No people found','Try a name, handle or skill.')}</div>`}if(ui.discoverTab==='topics'){const all=[...new Set(state.posts.flatMap(p=>p.tags))];const q=ui.query.replace(/^#/,'').toLowerCase();return `<div class="pad"><div class="topic-grid">${all.filter(t=>t.toLowerCase().includes(q)).map(t=>topicCard(t)).join('')||empty('No topics found','Try design, community or freelance.')}</div></div>`}const rows=feedPosts(state,{query:ui.query,type:ui.discoverType,remote:ui.remote,paid:ui.paid});return `${!ui.query&&ui.discoverType==='all'&&!ui.remote&&!ui.paid?`<div class="pad" style="padding-top:0"><div class="section-heading"><h2>Conversations to join</h2><span>In this sample</span></div><div class="topic-grid">${topicList.map(topicCard).join('')}</div><div class="section-heading"><h2>People worth knowing</h2><button class="tag" data-action="discover-tab" data-value="people">See all</button></div>${personRow(people[2])}</div>`:''}<div class="pad" style="padding-bottom:0;padding-top:4px"><div class="section-heading" style="margin-top:8px"><h2>${ui.query?'Search results':'Open possibilities'}</h2><span>${rows.length} posts</span></div></div>${rows.length?rows.map(p=>post(p)).join(''):empty('No matching opportunities','Change a filter or try a broader search.','search','<button class="button secondary" data-action="clear-search">Clear filters</button>')}`}
function topicCard(t){const count=state.posts.filter(p=>p.tags.includes(t)&&!state.blocked.includes(p.author)).length;return `<button class="topic-card" data-action="topic" data-value="${E(t)}"><span class="topic-icon">${icon(t==='BuildTogether'?'collab':t==='Freelance'?'gig':'spark')}</span><strong>#${E(t)}</strong><small>${count} sample ${count===1?'post':'posts'}</small></button>`}
function discover(){return `<div class="pad discover-intro"><h1 class="discover-title">Find your<br>next move.</h1><div class="search-wrap">${icon('search')}<input id="discoverSearch" type="search" value="${E(ui.query)}" placeholder="People, opportunities, #topics" aria-label="Search FYND"></div>${colliderFeature.entry()}</div>`+tabs([['opportunities','Posts'],['people','People'],['topics','Topics']],ui.discoverTab,'discover-tab')+(ui.discoverTab==='opportunities'?filters(ui.discoverType,'discover-type',true)+`<div class="pad" style="padding-top:0;padding-bottom:15px"><div class="discover-filters"><label><input type="checkbox" id="remoteFilter" ${ui.remote?'checked':''}> Remote</label><label><input type="checkbox" id="paidFilter" ${ui.paid?'checked':''}> Paid opportunity</label></div></div>`:'')+`<div id="discoverResults">${discoverResults()}</div>`}
function passportCard(p){return `<div class="passport"><div class="passport-head"><b class="passport-logo">FYND</b><span class="passport-edition">CAREER<br>PASSPORT</span></div><div class="platinum">PLATINUM</div>${icon('globe','passport-globe')}<div class="passport-name">${E(p.name.toUpperCase())}</div><div class="passport-role">${E(p.role)}</div><div class="passport-footer">DEMO</div></div>`}
function profile(){const p=person(state,ui.profileId)||state.profile;const own=p.id==='me',blocked=state.blocked.includes(p.id);const rows=(own&&ui.profileTab==='reposts'?allPosts(state):state.posts).filter(x=>x.author===p.id||(own&&ui.profileTab==='reposts'&&state.reposted.includes(x.id))).filter(x=>!state.blocked.includes(x.author));const profileRows=ui.profileTab==='reposts'?rows.filter(x=>state.reposted.includes(x.id)):rows.filter(x=>x.author===p.id);return `<div class="profile-top"><div class="profile-overview"><div class="profile-identity"><div class="profile-avatar-row">${avatar(p.id,'big')}${own?'<button class="button secondary small" data-action="edit-profile">Edit profile</button>':`<button class="icon-button" data-action="person-menu" data-value="${E(p.id)}" aria-label="Profile options">${icon('more')}</button>`}</div><h1 class="profile-name">${E(p.name)}</h1><p class="handle">@${E(p.handle)}</p><p class="bio">${E(p.bio)}</p><div class="profile-location">${icon('pin')}${E(p.location)}</div><div class="skill-tags">${p.skills.map(s=>`<span>${E(s)}</span>`).join('')}</div><div class="profile-stats"><span><strong>${p.followers+(state.following.includes(p.id)?1:0)}</strong>followers · sample</span>${own?`<button data-action="following-list"><strong>${state.following.length}</strong>following</button>`:''}</div></div>${own?`<div class="profile-passport-stack">${passportCard(p)}${colliderFeature.entry('passport')}</div>`:blocked?'<div class="notice">You blocked this profile in the demo. Their posts and messages are hidden.</div>':`<div class="button-row"><button class="button ${state.following.includes(p.id)?'secondary':'accent'}" data-action="follow" data-value="${E(p.id)}">${state.following.includes(p.id)?'Following':'Follow'}</button><button class="button secondary" data-action="chat" data-value="${E(p.id)}">${icon('mail')}Message</button></div>`}</div>${own?`<div class="quick-grid profile-tools"><button data-action="navigate" data-value="saved">${icon('bookmark')}Saved & interest</button><button data-action="navigate" data-value="progress">${icon('chart')}Progress</button><button data-action="navigate" data-value="research">${icon('spark')}Research</button></div>`:''}</div>`+tabs([['posts','Posts'],['work','Work'],...(own?[['reposts','Reposts']]:[])],ui.profileTab,'profile-tab')+(blocked?empty('Profile blocked','Manage blocked accounts in Settings.','block'):ui.profileTab==='work'?`<div class="pad">${own?`<p class="subtext" style="margin-bottom:16px">Work samples support your story. These examples are illustrative and have not been independently verified.</p>${state.evidence.map((e,i)=>`<div class="vault-item"><h3>${E(e)}</h3><p>Sample artifact · ${i===0?'Interaction study':'Service design'}</p><button class="button secondary small" data-action="evidence" data-value="${E(e)}">Inspect work sample ${icon('arrow')}</button></div>`).join('')}`:`<div class="vault-item"><h3>${E(p.skills[0])}</h3><p>Self-described skill. No supporting files attached in this sample.</p></div>`}</div>`:profileRows.length?profileRows.map(p=>post(p)).join(''):empty(ui.profileTab==='reposts'?'Keep good opportunities moving':'A fresh page',ui.profileTab==='reposts'?'Repost something from your feed and it will appear here.':'Posts from this person will appear here.','update'))}
function inbox(){const requestsAllowed=t=>state.settings.messages==='Everyone'||state.following.includes(t.id);const rows=state.threads.filter(t=>!state.blocked.includes(t.id)&&(ui.inboxTab==='requests'?t.request&&requestsAllowed(t):!t.request));const reqCount=state.threads.filter(t=>t.request&&!state.blocked.includes(t.id)&&requestsAllowed(t)).length;return tabs([['messages','Messages'],['requests',`Requests${reqCount?' · '+reqCount:''}`]],ui.inboxTab,'inbox-tab')+`<p class="inbox-note">${icon('shield')}<span>Demo conversations · stored only in this browser.</span></p>`+(rows.length?rows.map(t=>{const p=person(state,t.id);const m=t.messages.at(-1);return `<button class="thread-row ${t.unread?'is-unread':''}" data-action="chat" data-value="${E(t.id)}"><span class="avatar ${p.color}">${E(p.initials)}</span><div class="thread-text"><div class="thread-summary"><b>${E(p.name)}</b><small>${t.unread?'New':'Sample'}</small></div><p>${m?.from==='me'?'You: ':''}${E(m?.text||'Start a conversation')}</p></div>${t.unread?'<span class="unread"></span>':''}</button>`}).join(''):empty(ui.inboxTab==='requests'?'No message requests':'Start with a hello',ui.inboxTab==='requests'?'Requests are filtered using your message settings.':'Find someone in Discover and start a demo conversation.','mail','<button class="button" data-action="new-message">New conversation</button>'))}
function saved(){const tabsHTML=tabs([['saved',`Saved · ${state.saved.length}`],['interest',`My interest · ${state.applications.length}`]],ui.savedTab,'saved-tab');if(ui.savedTab==='saved'){const rows=feedPosts(state,{saved:true});return tabsHTML+(rows.length?rows.map(p=>post(p)).join(''):empty('Save a possibility','Tap the bookmark on any post to keep it here.','bookmark'))}return tabsHTML+`<div class="pad"><p class="subtext" style="margin-bottom:18px">Review packs and demo RSVPs live here. Simulated interest is never an employer acknowledgment.</p>${state.applications.map(a=>{const p=findPost(a.postId);return `<article class="op-card"><span class="status-pill">${E(a.status)}</span><h3>${E(p.title)}</h3><p>${E(p.org)} · ${E(types[p.type])}</p><button class="button secondary small" data-action="${a.status==='Draft'?'interest':'receipt'}" data-value="${E(p.id)}">${a.status==='Draft'?'Finish review':'View demo record'} ${icon('arrow')}</button></article>`}).join('')||empty('No interest yet','Explore a post to start an application, collaboration or event RSVP.','job')}</div>`}
const settingSwitch=(key,title,sub='')=>`<div class="setting-row"><div>${title}${sub?`<small>${sub}</small>`:''}</div><button class="switch" role="switch" aria-checked="${state.settings[key]}" aria-label="${title}" data-action="setting-toggle" data-value="${key}"><span></span></button></div>`;
function settings(){return `<div class="pad"><p class="subtext">Preferences apply to this preview on this browser.</p><div class="settings-label">${icon('shield')} PROFILE & AUDIENCE</div><div class="settings-group"><button class="setting-row" data-action="edit-profile"><span>Edit your profile</span>${icon('back','reverse')}</button><label class="setting-row"><span>Profile audience<small>Controls the public-profile preview</small></span><select data-setting="visibility" aria-label="Profile audience">${['Public profile','Followers only'].map(v=>`<option ${state.settings.visibility===v?'selected':''}>${v}</option>`).join('')}</select></label><button class="setting-row" data-action="public-preview"><span>Preview as a visitor</span>${icon('out')}</button><label class="setting-row"><span>Message requests<small>Filters sample requests in Inbox</small></span><select data-setting="messages" aria-label="Message requests">${['Everyone','People I follow'].map(v=>`<option ${state.settings.messages===v?'selected':''}>${v}</option>`).join('')}</select></label></div><div class="settings-label">${icon('bell')} ACTIVITY</div><div class="settings-group">${settingSwitch('likes','Likes')}${settingSwitch('replies','Replies')}${settingSwitch('opportunities','Opportunity posts')}${settingSwitch('digest','Weekly summary','Adds the demo summary to Activity')}</div><div class="settings-label">${icon('spark')} EXPERIENCE</div><div class="settings-group"><label class="setting-row"><span>Appearance</span><select data-setting="theme" aria-label="Appearance">${['dark','light','system'].map(v=>`<option value="${v}" ${state.settings.theme===v?'selected':''}>${v[0].toUpperCase()+v.slice(1)}</option>`).join('')}</select></label>${settingSwitch('reduceMotion','Reduce motion')}</div><div class="settings-label">${icon('user')} YOUR SPACE</div><div class="settings-group"><button class="setting-row" data-action="manage-hidden"><span>Muted & blocked</span><small>${state.muted.length+state.blocked.length} accounts</small></button><button class="setting-row" data-action="about"><span>About this prototype</span>${icon('file')}</button><button class="setting-row" data-action="reset" style="color:#d9778b"><span>Reset demo activity</span></button></div></div>`}
function activity(){const items=state.activity.filter(a=>state.settings[a.kind]&&!state.blocked.includes(a.author));return `<div class="pad" style="padding-bottom:0"><button class="tag" data-action="mark-read">Mark all as read</button></div>`+(items.map(a=>{const p=person(state,a.author);return `<button class="activity ${a.read?'read':''}" data-action="activity-open" data-value="${E(a.id)}"><span class="avatar ${p.color}">${E(p.initials)}</span><div class="activity-copy"><strong>${E(p.name)}</strong> ${E(a.text)}<small>Sample notification</small></div>${icon(a.kind==='likes'?'heart':a.kind==='replies'?'comment':'job')}</button>`}).join('')||empty('You’re all caught up','Your selected activity types will appear here.','bell'))+(state.settings.digest?`<button class="activity" data-action="navigate" data-value="progress">${icon('chart')}<span class="activity-copy"><strong>Your weekly preview</strong><small>See your saved opportunities and connections</small></span>${icon('arrow')}</button>`:'')}
function progress(){return `<div class="pad"><h1 class="section-title">From connection<br>to possibility.</h1><p class="subtext">Your activity in this demo.</p><div class="quick-grid"><button data-action="following-list">${icon('collab')}<b>${state.following.length}</b> following</button><button data-action="navigate" data-value="saved">${icon('bookmark')}<b>${state.saved.length}</b> saved</button><button data-action="navigate" data-value="inbox">${icon('mail')}<b>${state.threads.filter(t=>!t.request&&!state.blocked.includes(t.id)).length}</b> chats</button></div><div class="section-heading"><h2>Your next steps</h2></div>${state.applications.map(a=>{const p=findPost(a.postId);return `<div class="timeline-item"><h3>${E(p.title)}</h3><p>${E(a.status)} · ${E(p.org)}</p><button class="tag" data-action="${a.status==='Draft'?'interest':'receipt'}" data-value="${E(p.id)}">${a.status==='Draft'?'Review application':'Inspect demo record'}</button></div>`}).join('')}<div class="timeline-item"><h3>Let your work start a conversation.</h3><p>Share a project, something you learned, or a collaboration you’re looking for.</p><button class="tag" data-action="compose">Create a post</button></div></div>`}
function research(){const ps=feedPosts(state,{saved:true}).filter(p=>p.type!=='update');return `<div class="pad"><h1 class="section-title">Look a little closer.</h1><p class="subtext">Compare details from saved opportunity posts. These are sample listings, not live research results.</p><div class="section-heading"><h2>Your shortlist</h2><span>${ps.length} opportunities</span></div>${ps.length?ps.map(p=>`<article class="op-card"><span class="type-label">${E(types[p.type])}</span><h3 style="margin-top:12px">${E(p.title)}</h3><dl class="detail-list"><div class="detail-row"><dt>Compensation</dt><dd>${E(p.pay)}</dd></div><div class="detail-row"><dt>Commitment</dt><dd>${E(p.detail)}</dd></div><div class="detail-row"><dt>Skill overlap</dt><dd>${E(p.skills.filter(s=>state.profile.skills.includes(s)).join(', ')||'No exact overlap listed')}</dd></div><div class="detail-row"><dt>Source</dt><dd>${p.colliderMeta?'FYND sample catalog':'Author’s sample post'}</dd></div></dl><p>Still to check: team, terms and opportunity availability.</p><button class="button secondary small" data-action="detail" data-value="${E(p.id)}">View opportunity</button></article>`).join(''):empty('Build your shortlist','Save jobs, gigs, collaborations or events to compare them here.','bookmark')}<div class="notice">No match score or independent verification is implied. A real FYND research service would need live sources and evidence checks.</div></div>`}
function render({keepScroll=true}={}){const y=screen.scrollTop;document.body.dataset.view=ui.view;setTheme();header();const map={feed,discover,profile,inbox,saved,settings,notifications:activity,progress,research,collider:colliderFeature.screen};screen.innerHTML=(map[ui.view]||feed)();screen.scrollTop=keepScroll?y:0;}
function navigate(view){if(view==='create'){openComposer();return}if(!['feed','discover','profile','inbox','saved','settings','notifications','progress','research','collider'].includes(view))return;closeModal();ui.view=view;if(view==='profile')ui.profileId='me';render({keepScroll:false});screen.focus({preventScroll:true});}
function openProfile(id){if(!person(state,id))return;closeModal();ui.view='profile';ui.profileId=id;ui.profileTab='posts';render({keepScroll:false});}
function fitModal(){if(document.body.dataset.responsive==='true'&&!isEmbedded){for(const property of ['left','width','bottom','transform','max-height'])modal.style.removeProperty(property);return;}const r=$('.device').getBoundingClientRect();modal.style.left=(r.width?r.left:0)+'px';modal.style.width=(r.width||416)+'px';modal.style.bottom=Math.max(0,window.innerHeight-r.bottom+($('.status').offsetHeight?7:0))+'px';modal.style.transform='none';modal.style.maxHeight=Math.max(300,(r.height||800)-60)+'px';}
function openModal(title,html,context={}){const feedback=$('#modalFeedback');if(feedback)feedback.hidden=true;ui.modal=context;$('#modalTitle').textContent=title;modalBody.innerHTML=html;fitModal();if(!modal.open)modal.showModal();modalBody.scrollTop=0;}
function closeModal(){if(modal.open)modal.close();ui.modal=null;}
function findPost(id){return allPosts(state).find(p=>p.id===id)}
function showDetail(id){const p=findPost(id);if(!p)return;if(p.type==='update'){showComments(id);return}const a=state.applications.find(a=>a.postId===id&&a.status!=='Draft');openModal('Opportunity',`<div class="type-label">${icon(p.type)}${E(types[p.type])} · Sample</div><h1 class="section-title space-top">${E(p.title)}</h1><div class="person-row">${avatar(p.author)}<button class="person-info" data-action="profile" data-value="${E(p.author)}"><strong>${E(person(state,p.author).name)}</strong><small>${E(p.org)}</small></button></div><p class="post-text">${E(p.text)}</p><dl class="detail-list">${[['Compensation / cost',p.pay],['Location',p.location],['Commitment',p.detail],['Timing',p.deadline]].map(([k,v])=>`<div class="detail-row"><dt>${k}</dt><dd>${E(v)}</dd></div>`).join('')}</dl><div class="skill-tags">${(p.skills||[]).map(s=>`<span>${E(s)}</span>`).join('')}</div><div class="notice">Illustrative listing supplied by a fictional author. The organization, compensation and availability have not been verified.</div>${p.author==='me'?'<p class="subtext">This is your own demo opportunity.</p>':`<button class="button accent full" data-action="${a?'receipt':'interest'}" data-value="${E(id)}">${a?'View your demo record':{job:'Prepare application',gig:'Express interest',collab:'Let’s collaborate',event:'RSVP in demo'}[p.type]} ${icon('arrow')}</button>`}<div class="button-row"><button class="button secondary" data-action="save" data-value="${E(id)}">${icon('bookmark')}${state.saved.includes(id)?'Saved':'Save'}</button>${p.author!=='me'?`<button class="button secondary" data-action="chat" data-value="${E(p.author)}">${icon('mail')}Ask a question</button>`:''}</div>`,{type:'detail',id});}
function showComments(id){const p=findPost(id);if(!p)return;openModal('Conversation',`${post(p,{detail:true})}<h2 style="font-size:16px">Replies · ${p.comments.length}</h2><div>${p.comments.map(c=>`<div class="comment">${avatar(c.author,'small')}<div class="comment-content"><strong>${E(person(state,c.author).name)}</strong>${E(c.text)}</div></div>`).join('')||'<p class="subtext space-top">Start the conversation. Ask a question or share a useful connection.</p>'}</div><form id="commentForm" class="comment-form" data-post="${E(id)}"><textarea class="control" name="comment" maxlength="500" required rows="2" placeholder="Add a helpful reply…" aria-label="Your comment">${E(ui.commentDrafts[id]||'')}</textarea><button class="button accent" type="submit" aria-label="Add demo comment">${icon('send')}</button></form><p class="subtext" style="font-size:11px;margin-top:8px">Replies are added only to this demo.</p>`,{type:'comments',id});}
function refreshModal(){const y=modalBody.scrollTop;const c=ui.modal;if(c?.type==='detail')showDetail(c.id);else if(c?.type==='comments')showComments(c.id);else if(c?.type==='menu')menuForPerson(c.id,c.postId);modalBody.scrollTop=y;}
function draftData(){const f=$('#composeForm');if(!f)return state.draft;return Object.fromEntries(new FormData(f));}
function openComposer(){const d=state.draft;openModal('Create a post',`<form id="composeForm"><div class="compose-author">${avatar('me')}<div><strong>${E(state.profile.name)}</strong><div class="author-meta">@${E(state.profile.handle)}</div></div></div><div class="type-picker">${Object.entries(types).map(([id,t])=>`<button type="button" class="chip ${d.type===id?'active':''}" data-action="compose-type" data-value="${id}">${t}</button>`).join('')}</div><input type="hidden" name="type" value="${E(d.type)}"><textarea class="control composer-text" name="text" maxlength="1000" placeholder="Share an opening, an idea, or something you’re making…" aria-label="Post text" required>${E(d.text)}</textarea><div class="char-count"><span id="charCount">${d.text.length}</span> / 1,000</div>${d.type!=='update'?`<label class="field"><span>Opportunity title</span><input class="control" name="title" maxlength="90" value="${E(d.title)}" placeholder="What’s the opportunity?" required></label><label class="field"><span>${d.type==='event'?'Cost / entry':'Compensation (include unpaid if applicable)'}</span><input class="control" name="pay" maxlength="70" value="${E(d.pay)}" placeholder="${d.type==='event'?'Free entry':'₹40k fixed / paid / unpaid'}" required></label>${d.type!=='event'?`<label class="field"><span>Compensation status</span><select class="control" name="compensationType"><option value="paid" ${d.compensationType==='paid'?'selected':''}>Paid</option><option value="unpaid" ${d.compensationType==='unpaid'?'selected':''}>Unpaid / equity only</option></select></label>`:''}<label class="field"><span>Location</span><input class="control" name="location" maxlength="70" value="${E(d.location)}" placeholder="Remote · India / Bengaluru" required></label><label class="field"><span>${d.type==='event'?'Date, time and capacity':'Timing, commitment and scope'}</span><input class="control" name="detail" maxlength="120" value="${E(d.detail)}" placeholder="${d.type==='event'?'24 Sep · 6:30 PM · 40 places':'Part-time · 2 weeks · brand identity'}" required></label>`:''}<label class="field"><span>Topics (up to four)</span><input class="control" name="tags" maxlength="120" value="${E(d.tags)}" placeholder="#ProductDesign #BuildTogether"></label><label class="field"><span>Post audience</span><select class="control" name="audience"><option ${d.audience==='Public'?'selected':''}>Public</option><option ${d.audience==='Followers'?'selected':''}>Followers</option></select></label><p class="notice">Audience is shown on your demo post. This preview does not publish to a real social network.</p><div id="composeError" class="error" role="alert"></div><button class="button accent full" type="submit">Preview post ${icon('arrow')}</button></form>`,{type:'compose'});}
function previewComposer(data){state.draft={...state.draft,...data};persist();if(!data.text.trim()||(data.type!=='update'&&(!data.title.trim()||!data.pay.trim()||!data.location.trim()||!data.detail.trim())))return;ui.draftReview={...data};openModal('Review your post',`<div class="compose-author">${avatar('me')}<strong>${E(state.profile.name)}</strong></div><span class="type-label">${E(types[data.type])} · ${E(data.audience)}</span><h2 class="section-title space-top">${E(data.type==='update'?'Your update':data.title)}</h2><p class="post-text">${E(data.text)}</p>${data.type!=='update'?`<dl class="detail-list">${[['Compensation / cost',data.pay],['Location',data.location],['Timing',data.detail]].map(([k,v])=>`<div class="detail-row"><dt>${k}</dt><dd>${E(v)}</dd></div>`).join('')}</dl>`:''}<p class="notice">This adds the post to your local demo feed. Other people will not see it.</p><div class="button-row"><button class="button secondary" data-action="compose">Edit</button><button class="button accent" data-action="publish">Add to demo feed</button></div>`,{type:'compose-review'});}
function showChat(id){const p=person(state,id);if(!p||id==='me')return;if(state.blocked.includes(id)){notify('Unblock this person in Settings to message them.');return}const t=state.threads.find(t=>t.id===id);if(t?.request&&state.settings.messages!=='Everyone'&&!state.following.includes(id)){notify('This request is hidden by your message preferences.');return}if(t)t.unread=false;persist();render();openModal(p.name,`<div class="chat-intro">${avatar(id,'big')}<p style="margin-top:12px">${E(p.role)}</p><p>Demo conversation · no messages leave this browser</p></div><div id="chatMessages">${(t?.messages||[]).map(m=>`<div class="chat-bubble ${m.from==='me'?'mine':''}">${E(m.text)}<div class="chat-time">${E(m.time)}</div></div>`).join('')||'<p class="subtext">A useful introduction can open a door.</p>'}</div>${t?.request?`<div class="notice">Accept this sample request to reply.</div><div class="button-row"><button class="button secondary" data-action="decline-request" data-value="${E(id)}">Decline</button><button class="button accent" data-action="accept-request" data-value="${E(id)}">Accept request</button></div>`:`<form id="messageForm" class="comment-form chat-compose" data-person="${E(id)}"><textarea class="control" name="message" rows="2" maxlength="2000" required placeholder="Write a message…" aria-label="Message to ${E(p.name)}"></textarea><button type="submit" class="button accent" aria-label="Add demo message">${icon('send')}</button></form>`}`,{type:'chat',id});}
function showInterest(id){const p=findPost(id);if(!p)return;const prior=state.applications.find(a=>a.postId===id);if(prior&&prior.status!=='Draft'){showReceipt(id);return}const draft=ui.interest?.id===id?ui.interest:prior;ui.interest={id,intro:draft?.intro||'',evidence:draft?.evidence||[]};const event=p.type==='event';openModal(event?'Review RSVP':'Prepare an introduction',`<span class="type-label">${E(types[p.type])}</span><h2 class="section-title space-top">${E(p.title)}</h2><p class="subtext">For ${E(person(state,p.author).name)} · ${E(p.org)}</p><form id="interestForm" data-post="${E(id)}">${!event?`<label class="field"><span>Your introduction</span><textarea class="control" name="intro" maxlength="1500" required>${E(draft?.intro||'')}</textarea></label><p class="review-label">Include approved work samples</p>${state.evidence.map(e=>`<label class="check-row"><input type="checkbox" name="evidence" value="${E(e)}" ${draft?.evidence?.includes(e)?'checked':''}><span>${E(e)}<br><small class="subtext">Illustrative artifact</small></span></label>`).join('')}`:`<dl class="detail-list"><div class="detail-row"><dt>When</dt><dd>${E(p.deadline)}</dd></div><div class="detail-row"><dt>Where</dt><dd>${E(p.location)}</dd></div></dl>`}<p class="notice">Next, review the exact information in your demo ${event?'RSVP':'application'}. Contact details are excluded.</p><button type="submit" class="button accent full">Review ${event?'RSVP':'introduction'} ${icon('arrow')}</button></form>`,{type:'interest',id});}
function showInterestReview(id,data){const p=findPost(id);ui.interest={id,intro:data.intro||'',evidence:data.evidence||[]};openModal('Review before sharing',`<p class="review-label">Recipient</p><h3>${E(person(state,p.author).name)} · ${E(p.org)}</h3><p class="subtext">${E(p.title)}</p><p class="review-label">Included</p><div class="vault-item"><strong>${E(state.profile.name)}</strong><p>${E(state.profile.role)} · ${E(state.profile.location)}</p><p>${E(state.profile.bio)}</p></div>${data.intro?`<p class="review-label">Your message</p><p class="post-text">${E(data.intro)}</p>`:''}<p class="review-label">Work samples</p><p class="subtext">${E(data.evidence?.join(', ')||'No work samples included')}</p><p class="notice">In the live product, this step would send only the reviewed information to the named recipient. Here it creates a local simulation record. No employer is contacted and no event place is reserved.</p><div class="button-row"><button class="button secondary" data-action="interest" data-value="${E(id)}">Edit</button><button class="button accent" data-action="submit-interest">Confirm simulation</button></div>`,{type:'interest-review',id});}
function showReceipt(id){const p=findPost(id),a=state.applications.find(a=>a.postId===id);if(!a)return;openModal('Your demo record',`<div style="color:var(--accent);margin-bottom:15px">${icon('check')}</div><h2 class="section-title">${E(a.status)}</h2><p class="subtext">${E(p.title)} · ${E(p.org)}</p><p class="review-label">Introduction</p><p class="post-text">${E(a.intro||'Sample event RSVP')}</p><p class="review-label">Included work samples</p><p>${E(a.evidence.join(', ')||'None')}</p><div class="notice">Saved in this browser only. This is not a delivery receipt, application acknowledgment or event booking.</div><button class="button secondary full" data-action="interest-list">View my interest</button>`,{type:'receipt',id});}
function editProfile(){const p=state.profile;openModal('Edit profile',`<form id="profileForm">${[['name','Name',p.name,50],['role','What you do',p.role,80],['location','Location',p.location,80],['bio','Bio',p.bio,240],['skills','Skills (comma separated)',p.skills.join(', '),180]].map(([name,label,value,max])=>`<label class="field"><span>${label}</span>${name==='bio'?`<textarea class="control" name="${name}" maxlength="${max}" required>${E(value)}</textarea>`:`<input class="control" name="${name}" value="${E(value)}" maxlength="${max}" required>`}</label>`).join('')}<p class="notice">Profile edits update your demo posts, Passport and application review.</p><button class="button accent full" type="submit">Save profile</button></form>`,{type:'edit-profile'});}
function menuForPerson(id,postId){const p=person(state,id);openModal(postId?'Post options':'Profile options',`<div class="action-list">${postId?`<button data-action="save" data-value="${E(postId)}">${icon('bookmark')}${state.saved.includes(postId)?'Remove from saved':'Save post'}</button><button data-action="share" data-value="${E(postId)}">${icon('copy')}Copy post text</button>`:''}${id!=='me'?`<button data-action="mute-person" data-value="${E(id)}">${icon('mute')}${state.muted.includes(id)?'Unmute':'Mute'} ${E(p.name)}</button><button data-action="confirm-block" data-value="${E(id)}">${icon('block')}Block ${E(p.name)}</button>${postId?`<button class="danger-text" data-action="report" data-value="${E(postId)}">${icon('flag')}Report this post</button>`:''}`:''}</div>`,{type:'menu',id,postId});}
function manageHidden(){openModal('Muted & blocked',`<h3 style="font-size:15px">Muted profiles</h3>${state.muted.map(id=>`<div class="person-row">${avatar(id)}<div class="person-info"><strong>${E(person(state,id).name)}</strong></div><button class="pill-button outline" data-action="unmute" data-value="${id}">Unmute</button></div>`).join('')||'<p class="subtext space-top">No muted profiles.</p>'}<h3 class="space-top" style="font-size:15px">Blocked profiles</h3>${state.blocked.map(id=>`<div class="person-row">${avatar(id)}<div class="person-info"><strong>${E(person(state,id).name)}</strong></div><button class="pill-button outline" data-action="unblock" data-value="${id}">Unblock</button></div>`).join('')||'<p class="subtext space-top">No blocked profiles.</p>'}`,{type:'manage-hidden'});}
function showWork(id){const p=findPost(id);openModal('Flow / Material studies',`<img class="post-image" src="assets/flow-study.png" alt="Glass and silver material study" width="1448" height="1086"><h2 class="section-title space-top">A little more human.</h2><p class="subtext">An illustrative exploration of material, reflection and form. This original artwork was generated for the FYND prototype.</p><div class="notice">Fictional portfolio sample. It does not verify a person’s authorship, employment, or business outcomes.</div>${p?`<button class="button secondary full" data-action="comments" data-value="${E(p.id)}">Discuss this work ${icon('comment')}</button>`:''}`,{type:'work'});}
function action(name,value,el){if(colliderFeature.handleAction(name,value))return;switch(name){
case'tools':openModal('Your tools',toolsMarkup('demo',icon),{type:'tools'});break;
case'navigate':navigate(value);break;
case'profile':openProfile(value);break;
case'close':closeModal();break;
case'feed-tab':ui.feedTab=value;render({keepScroll:false});break;
case'feed-type':ui.feedType=value;render({keepScroll:false});break;
case'discover-tab':ui.discoverTab=value;render({keepScroll:false});break;
case'discover-type':ui.discoverType=value;render();break;
case'profile-tab':ui.profileTab=value;render();break;
case'inbox-tab':ui.inboxTab=value;render({keepScroll:false});break;
case'saved-tab':ui.savedTab=value;render({keepScroll:false});break;
case'topic':ui.query=value;ui.discoverTab='opportunities';ui.discoverType='all';ui.paid=false;ui.remote=false;navigate('discover');break;
case'clear-search':ui.query='';ui.discoverType='all';ui.paid=false;ui.remote=false;render();break;
case'follow':if(value==='me'||!person(state,value)||state.blocked.includes(value))return;toggle(state.following,value);persist();render();refreshModal();break;
case'like':case'save':case'repost':{if(!findPost(value))return;const key={like:'liked',save:'saved',repost:'reposted'}[name];const added=toggle(state[key],value);persist();render();refreshModal();if(name==='save')notify(added?'Saved to your opportunities':'Removed from saved');if(name==='repost')notify(added?'Reposted to your demo profile':'Repost removed');break;}
case'comments':showComments(value);break;
case'detail':showDetail(value);break;
case'work':showWork(value);break;
case'evidence':if(value==='Flow exploration'){showWork();}else openModal('Common service blueprint',`<h2 class="section-title">From friction to flow.</h2><p class="subtext">A sample service-design artifact describing the customer journey.</p><dl class="detail-list"><div class="detail-row"><dt>Discover</dt><dd>Clarify the customer’s goal</dd></div><div class="detail-row"><dt>Decide</dt><dd>Make trade-offs visible</dd></div><div class="detail-row"><dt>Act</dt><dd>Make the next step clear</dd></div></dl><p class="notice">Illustrative content. No source file, authorship proof or measured outcome attached.</p>`,{type:'evidence'});break;
case'compose':openComposer();break;
case'compose-type':state.draft={...state.draft,...draftData(),type:value};persist();openComposer();break;
case'publish':{if(!ui.draftReview)return;try{const p=publishPost(state,ui.draftReview);ui.draftReview=null;persist();ui.feedTab='for-you';ui.feedType='all';navigate('feed');notify('Your post is in the demo feed');}catch(e){notify(e.message)}break;}
case'post-menu':{const p=findPost(value);if(p)menuForPerson(p.author,p.id);break;}
case'person-menu':menuForPerson(value);break;
case'share':{const p=findPost(value);if(!p)return;const text=[person(state,p.author).name,p.title,p.text,p.pay,p.location,...p.tags.map(t=>'#'+t)].filter(Boolean).join('\n');openModal('Copy this post',`<p class="subtext">Copy the post text to share wherever you like. This sample has no public post link.</p><textarea class="control space-top" readonly id="shareText" aria-label="Post text to copy" style="min-height:180px">${E(text)}</textarea><button class="button accent full space-top" data-action="copy-text">${icon('copy')}Copy text</button>`,{type:'share',id:value});break;}
case'copy-text':{const textarea=$('#shareText');if(navigator.clipboard?.writeText){navigator.clipboard.writeText(textarea.value).then(()=>notify('Post text copied')).catch(()=>{textarea.focus();textarea.select();notify('Select and copy the highlighted text')});}else{textarea.focus();textarea.select();notify('Select and copy the highlighted text');}break;}
case'new-message':openModal('Start a conversation',`<p class="subtext">Choose a person for a local demo conversation.</p>${people.filter(p=>p.id!=='me'&&!state.blocked.includes(p.id)).map(p=>`<button class="thread-row" style="padding-left:0;padding-right:0" data-action="chat" data-value="${p.id}"><span class="avatar ${p.color}">${p.initials}</span><div class="person-info"><strong>${E(p.name)}</strong><small>${E(p.role)}</small></div>${icon('arrow')}</button>`).join('')}`,{type:'new-message'});break;
case'chat':showChat(value);break;
case'accept-request':{const t=state.threads.find(t=>t.id===value);if(t)t.request=false;persist();render();showChat(value);break;}
case'decline-request':state.threads=state.threads.filter(t=>t.id!==value);persist();closeModal();render();notify('Demo request declined');break;
case'interest':showInterest(value);break;
case'submit-interest':{const d=ui.interest;if(!d)return;try{submitInterest(state,d.id,d.intro,d.evidence);persist();render();showReceipt(d.id);}catch(e){notify(e.message)}break;}
case'receipt':showReceipt(value);break;
case'interest-list':ui.savedTab='interest';navigate('saved');break;
case'edit-profile':editProfile();break;
case'following-list':openModal('People you follow',state.following.length?state.following.map(id=>personRow(person(state,id))).join(''):empty('A fresh network','Follow a person in Discover to start.','collab'),{type:'following-list'});break;
case'setting-toggle':if(typeof state.settings[value]==='boolean'){state.settings[value]=!state.settings[value];persist();render()}break;
case'public-preview':openModal('Profile as a new visitor',state.settings.visibility==='Followers only'?`<div class="chat-intro">${avatar('me','big')}<h2 class="section-title space-top">${E(state.profile.name)}</h2><p>@${E(state.profile.handle)}</p></div><div class="notice">Only followers can see this profile’s bio, work and posts. This is the simulated view for someone who does not follow you.</div>`:`${passportCard(state.profile)}<p class="bio">${E(state.profile.bio)}</p><p class="profile-location">${E(state.profile.location)}</p><div class="notice">A visitor can see the profile, work and public posts. Contact details and application history are excluded.</div>${state.posts.filter(p=>p.author==='me'&&p.audience!=='Followers').map(p=>`<div class="vault-item"><p class="post-text">${E(p.text)}</p></div>`).join('')}`,{type:'public-preview'});break;
case'mute-person':toggle(state.muted,value);persist();closeModal();render();notify(state.muted.includes(value)?'Their posts are hidden from your feeds':'Profile unmuted');break;
case'confirm-block':openModal('Block this person?',`<h2 class="section-title">${E(person(state,value).name)}</h2><p class="subtext">Their posts and conversations will be hidden in your demo. You can undo this in Settings.</p><button class="button danger full space-top" data-action="block-person" data-value="${E(value)}">Block in demo</button>`,{type:'block'});break;
case'block-person':if(!state.blocked.includes(value))state.blocked.push(value);state.following=state.following.filter(id=>id!==value);persist();closeModal();render();notify('Profile blocked in this demo');break;
case'manage-hidden':manageHidden();break;
case'unmute':state.muted=state.muted.filter(id=>id!==value);persist();render();manageHidden();break;
case'unblock':state.blocked=state.blocked.filter(id=>id!==value);persist();render();manageHidden();break;
case'report':openModal('Report a sample post',`<p class="subtext">Choose a reason to preview the reporting flow.</p><form id="reportForm" data-post="${E(value)}"><label class="field"><span>Reason</span><select class="control" name="reason"><option>Misleading opportunity</option><option>Spam or unwanted promotion</option><option>Harassment</option><option>Other</option></select></label><p class="notice">This records your selection locally. There is no moderation team connected to this demo.</p><button class="button full" type="submit">Record demo report</button></form>`,{type:'report'});break;
case'mark-read':state.activity.forEach(a=>a.read=true);persist();render();notify('All activity marked read');break;
case'activity-open':{const a=state.activity.find(a=>a.id===value);if(a){a.read=true;persist();render();a.kind==='opportunities'?showDetail(a.postId):showComments(a.postId)}break;}
case'about':openModal('About FYND Studio',`<h2 class="section-title">A social network<br>for possibilities.</h2><p class="subtext">Discover people and opportunities. Share work, follow conversations and choose what happens next.</p><div class="notice">This is a functional product prototype with fictional content. Posts, follows, comments, applications and messages are stored only in this browser. It has no real member accounts, live messaging, employer submissions, identity verification connected AI research or a live job scraper. Lynk Collider searches an illustrative job catalog.</div><p class="subtext">Artwork: original generated material study for this prototype. Interface: FYND Studio, concept 14.</p>`,{type:'about'});break;
case'reset':openModal('Reset this preview?',`<p class="subtext">This removes your demo posts, messages, reactions and profile edits from this browser and restores the sample content.</p><div class="button-row"><button class="button secondary" data-action="close">Keep my changes</button><button class="button danger" data-action="reset-confirm">Reset demo</button></div>`,{type:'reset'});break;
case'reset-confirm':colliderFeature.reset();state=initialState();applyDesignDefaults();persist();ui.feedTab='for-you';ui.feedType='all';ui.query='';navigate('feed');notify('Sample content restored');break;
}}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el){e.preventDefault();try{action(el.dataset.action,el.dataset.value,el);if(ui.modal?.type==='following-list'&&el.dataset.action==='follow')action('following-list');}catch(err){console.error(err);notify('That action could not be completed. Please try again.')}}});
document.addEventListener('input',e=>{if(e.target.id==='discoverSearch'){ui.query=e.target.value;$('#discoverResults').innerHTML=discoverResults();}if(e.target.closest('#commentForm'))ui.commentDrafts[e.target.closest('#commentForm').dataset.post]=e.target.value;if(e.target.closest('#composeForm')){state.draft={...state.draft,...draftData()};persist();if($('#charCount'))$('#charCount').textContent=state.draft.text.length;}});
document.addEventListener('change',e=>{if(e.target.id==='remoteFilter'||e.target.id==='paidFilter'){ui[e.target.id==='remoteFilter'?'remote':'paid']=e.target.checked;$('#discoverResults').innerHTML=discoverResults();}if(e.target.dataset.setting){const key=e.target.dataset.setting;state.settings[key]=e.target.value;persist();render();}});
document.addEventListener('submit',e=>{const f=e.target;if(!['composeForm','commentForm','messageForm','profileForm','interestForm','reportForm','colliderForm'].includes(f.id))return;e.preventDefault();const d=Object.fromEntries(new FormData(f));try{
 if(colliderFeature.handleSubmit(f))return;
 if(f.id==='composeForm'){previewComposer({...state.draft,...d});}
 if(f.id==='commentForm'){const id=f.dataset.post;addComment(state,id,d.comment);delete ui.commentDrafts[id];persist();render();showComments(id);modalBody.scrollTop=modalBody.scrollHeight;}
 if(f.id==='messageForm'){const id=f.dataset.person;sendMessage(state,id,d.message);persist();render();showChat(id);modalBody.scrollTop=modalBody.scrollHeight;}
 if(f.id==='profileForm'){if(!d.name.trim()||!d.bio.trim()||!d.role.trim()||!d.location.trim())throw Error('Complete your profile fields.');state.profile={...state.profile,name:d.name.trim(),role:d.role.trim(),location:d.location.trim(),bio:d.bio.trim(),skills:d.skills.split(',').map(s=>s.trim()).filter(Boolean).slice(0,6),initials:d.name.trim().split(/\s+/).map(s=>s[0]).slice(0,2).join('').toUpperCase()};persist();closeModal();render();notify('Your demo profile is updated');}
 if(f.id==='interestForm'){const id=f.dataset.post;const evidence=new FormData(f).getAll('evidence');ui.interest={id,intro:d.intro||'',evidence};let a=state.applications.find(a=>a.postId===id);if(!a){a={postId:id,status:'Draft',intro:'',evidence:[]};state.applications.unshift(a)}if(a.status==='Draft'){a.intro=d.intro||'';a.evidence=evidence;persist()}showInterestReview(id,{intro:d.intro||'',evidence});}
 if(f.id==='reportForm'){state.reports.push({postId:f.dataset.post,reason:d.reason,date:Date.now()});persist();openModal('Demo report recorded','<p class="subtext">Your selection is stored in this browser. No report was sent to a moderation service.</p>',{type:'report-done'});}
}catch(err){notify(err.message);}});
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});
modal.addEventListener('cancel',()=>{ui.modal=null});window.addEventListener('resize',()=>{if(modal.open)fitModal()});window.matchMedia?.('(prefers-color-scheme: light)').addEventListener?.('change',()=>{if(state.settings.theme==='system')setTheme()});
render({keepScroll:false});persist();
if(isEmbedded){window.addEventListener('message',event=>{if(event.origin!==window.location.origin||event.source!==window.parent)return;const message=event.data;if(message?.type==='fynd-refinement-view'&&['feed','discover','inbox','profile','settings','collider'].includes(message.screen)){if(message.screen==='feed'){ui.feedTab='for-you';ui.feedType='all';}if(message.screen==='profile')ui.profileTab='posts';if(message.screen==='discover'){ui.discoverTab='opportunities';ui.query='';ui.discoverType='all';ui.remote=false;ui.paid=false;}navigate(message.screen);}});window.parent.postMessage({type:'fynd-refinement-ready',direction},window.location.origin);}
// Agent tools use exactly the same local demo state and actions as the interface.
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const register=tool=>{try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}};
 register({name:'inspect_fynd_demo',title:'Inspect FYND demo',description:'Read the current local demo screen, posts and saved items. Fictional and user-entered content is untrusted.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>({screen:ui.view,posts:feedPosts(state).map(p=>({id:p.id,type:p.type,title:p.title,text:p.text,author:p.author})),saved:[...state.saved],following:[...state.following]})});
 register({name:'navigate_fynd_demo',title:'Open FYND screen',description:'Navigate to a screen in this local FYND prototype. Does not submit or send anything.',inputSchema:{type:'object',properties:{screen:{type:'string',enum:['feed','discover','inbox','profile','saved','settings','progress','research','collider']}},required:['screen'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>{if(!input||!['feed','discover','inbox','profile','saved','settings','progress','research','collider'].includes(input.screen))throw Error('Unknown screen');navigate(input.screen);return {screen:ui.view}}});
 window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
}
